-- ==============================================================================
-- UNB PREMIUM — DATABASE MIGRATION: 0035_rename_commission_to_platform_fee.sql
-- ==============================================================================
-- Purpose:
--   Renames "Commission" (کمیشن) to "Platform Fee" (پلیٹ فارم فیس) in all
--   user-facing text generated by PostgreSQL functions, triggers, exceptions,
--   and notifications.
--
-- Strict Preservation Invariants:
--   - ZERO schema renames: table names, column names, enums, RPC function names,
--     JSON payload keys, and audit log action_type values remain 100% identical.
--   - SQL Syntax Construct Invariant: constructs like coalesce, nullif, greatest,
--     and trim are NEVER schema-qualified with pg_catalog.
--   - Security: SECURITY DEFINER, SET search_path = '', and existing role grants preserved.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. set_writer_commission_terms
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_writer_commission_terms(
    p_writer_id uuid,
    p_custom_rate numeric,
    p_unpaid_limit numeric,
    p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_old record;
    v_new_limit numeric(12,2);
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can modify writer platform fee terms.';
    END IF;

    IF p_reason IS NULL OR trim(p_reason) = '' THEN
        RAISE EXCEPTION 'A justification reason is required to modify writer platform fee terms.';
    END IF;

    IF p_custom_rate IS NOT NULL AND (p_custom_rate < 0 OR p_custom_rate > 100) THEN
        RAISE EXCEPTION 'Custom platform fee rate must be between 0%% and 100%%. Provided: %', p_custom_rate;
    END IF;

    IF p_unpaid_limit IS NOT NULL AND p_unpaid_limit < 0 THEN
        RAISE EXCEPTION 'Unpaid platform fee limit cannot be negative. Provided: %', p_unpaid_limit;
    END IF;

    SELECT * INTO v_old FROM public.writer_profiles WHERE id = p_writer_id;
    IF v_old.id IS NULL THEN
        RAISE EXCEPTION 'Writer profile not found: %', p_writer_id;
    END IF;

    v_new_limit := coalesce(p_unpaid_limit, v_old.unpaid_commission_limit);

    -- Past ledger rows are NEVER modified. New rate applies to future orders.
    UPDATE public.writer_profiles
    SET custom_commission_rate = p_custom_rate,
        unpaid_commission_limit = v_new_limit,
        updated_at = pg_catalog.now()
    WHERE id = p_writer_id;

    -- Reconcile balance and pause status against the new limit
    PERFORM public.reconcile_writer_unpaid_commission(p_writer_id);

    -- Notify writer
    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        body,
        link,
        entity_refs,
        is_read,
        created_at
    ) VALUES (
        p_writer_id,
        'commission_terms_updated',
        'پلیٹ فارم فیس کی شرائط اپ ڈیٹ (Platform Fee Terms Updated)',
        'آپ کے اکاؤنٹ کی پلیٹ فارم فیس اور حد کی شرائط اپ ڈیٹ کر دی گئی ہیں۔ وجہ: ' || trim(p_reason),
        trim(p_reason),
        '/writer/finances',
        pg_catalog.jsonb_build_object(
            'writer_id', p_writer_id,
            'custom_commission_rate', p_custom_rate,
            'unpaid_commission_limit', v_new_limit,
            'reason', trim(p_reason)
        ),
        false,
        pg_catalog.now()
    );

    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'SET_WRITER_COMMISSION_TERMS',
        'writer_profiles',
        p_writer_id::text,
        pg_catalog.jsonb_build_object(
            'custom_commission_rate', v_old.custom_commission_rate,
            'unpaid_commission_limit', v_old.unpaid_commission_limit
        ),
        pg_catalog.jsonb_build_object(
            'custom_commission_rate', p_custom_rate,
            'unpaid_commission_limit', v_new_limit,
            'reason', trim(p_reason)
        ),
        pg_catalog.now()
    );

    RETURN pg_catalog.jsonb_build_object(
        'success', true,
        'writer_id', p_writer_id,
        'custom_commission_rate', p_custom_rate,
        'unpaid_commission_limit', v_new_limit
    );
END;
$$;

REVOKE ALL ON FUNCTION public.set_writer_commission_terms(uuid, numeric, numeric, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_writer_commission_terms(uuid, numeric, numeric, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 2. trg_protect_writer_profile_columns
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.trg_protect_writer_profile_columns()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
    -- Only platform administrators may directly update protected financial/commission columns
    IF NOT public.is_admin() THEN
        IF NEW.custom_commission_rate IS DISTINCT FROM OLD.custom_commission_rate THEN
            RAISE EXCEPTION 'Unauthorized: Writer custom platform fee rate is managed by administrators.';
        END IF;
        IF NEW.unpaid_commission_limit IS DISTINCT FROM OLD.unpaid_commission_limit THEN
            RAISE EXCEPTION 'Unauthorized: Unpaid platform fee limit is managed by administrators.';
        END IF;
        IF NEW.current_unpaid_commission IS DISTINCT FROM OLD.current_unpaid_commission THEN
            RAISE EXCEPTION 'Unauthorized: Unpaid platform fee balance is managed exclusively by ledger reconciliation.';
        END IF;
        IF NEW.is_orders_paused_for_commission IS DISTINCT FROM OLD.is_orders_paused_for_commission THEN
            RAISE EXCEPTION 'Unauthorized: Order pause state is automated based on accrued platform fee threshold.';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

-- ------------------------------------------------------------------------------
-- 3. get_checkout_options
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_checkout_options(p_novel_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_novel record;
    v_writer record;
    v_payment_methods jsonb;
    v_open_order_number text;
    v_pen_name text;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required to initiate checkout.';
    END IF;

    -- Fetch novel
    SELECT * INTO v_novel
    FROM public.novels
    WHERE id = p_novel_id;

    IF v_novel.id IS NULL OR v_novel.status::text != 'published' THEN
        RAISE EXCEPTION 'Novel not found or is currently not available for purchase.';
    END IF;

    -- Check if caller is author of this novel
    IF v_novel.writer_id = v_caller_id THEN
        RAISE EXCEPTION 'Authors cannot purchase their own novels.';
    END IF;

    -- Check if reader already owns active entitlement
    IF EXISTS (
        SELECT 1 FROM public.purchase_entitlements
        WHERE reader_id = v_caller_id
          AND novel_id = p_novel_id
          AND is_revoked = false
    ) THEN
        RAISE EXCEPTION 'You already hold an active purchase entitlement for this novel.';
    END IF;

    -- Fetch writer profile
    SELECT * INTO v_writer
    FROM public.writer_profiles
    WHERE id = v_novel.writer_id;

    IF v_writer.id IS NULL OR v_writer.status::text != 'approved' THEN
        RAISE EXCEPTION 'This author is currently not eligible to receive orders.';
    END IF;

    IF v_writer.is_orders_paused_for_commission THEN
        RAISE EXCEPTION 'Orders for this author are currently paused due to platform fee limits.';
    END IF;

    v_pen_name := coalesce(v_writer.pen_name_urdu, v_writer.pen_name_english, 'Author');

    -- Check if reader has an existing open order for this novel
    SELECT order_number INTO v_open_order_number
    FROM public.orders
    WHERE reader_id = v_caller_id
      AND novel_id = p_novel_id
      AND status::text IN ('pending_payment', 'payment_submitted', 'rejected', 'disputed')
    ORDER BY created_at DESC
    LIMIT 1;

    -- Collect active payment methods with strictly masked accounts
    SELECT coalesce(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'id', wpm.id,
                'method_type', wpm.method_type,
                'bank_name', wpm.bank_name,
                'account_title', wpm.account_title,
                'account_number_tail', wpm.account_number_tail,
                'qr_code_path', wpm.qr_code_path,
                'instructions', wpm.instructions
            )
            ORDER BY wpm.created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_payment_methods
    FROM public.writer_payment_methods wpm
    WHERE wpm.writer_id = v_novel.writer_id
      AND wpm.is_active = true;

    RETURN pg_catalog.jsonb_build_object(
        'novel_id', v_novel.id,
        'title_english', v_novel.title_english,
        'title_urdu', v_novel.title_urdu,
        'price_pkr', v_novel.price_pkr,
        'writer_id', v_novel.writer_id,
        'writer_pen_name', v_pen_name,
        'has_open_order', (v_open_order_number IS NOT NULL),
        'open_order_number', v_open_order_number,
        'payment_methods', v_payment_methods
    );
END;
$$;

REVOKE ALL ON FUNCTION public.get_checkout_options(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_checkout_options(uuid) TO authenticated;

-- ------------------------------------------------------------------------------
-- 4. create_order
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_order(
    p_novel_id uuid,
    p_payment_method_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_novel record;
    v_writer record;
    v_method record;
    v_min_price integer;
    v_max_price numeric(10,2);
    v_max_orders_per_hour integer;
    v_recent_order_count integer;
    v_default_rate numeric(5,2);
    v_applied_rate numeric(5,2);
    v_commission_pkr numeric(10,2);
    v_writer_share_pkr numeric(10,2);
    v_order_number text;
    v_order_id uuid;
    v_instructions jsonb;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required to create an order.';
    END IF;

    -- Fetch platform settings
    SELECT
        coalesce(min_novel_price_pkr, 50),
        coalesce(max_novel_price_pkr, 5000.00),
        coalesce(max_orders_per_hour, 5),
        coalesce(default_commission_rate, 20.00)
    INTO
        v_min_price,
        v_max_price,
        v_max_orders_per_hour,
        v_default_rate
    FROM public.platform_settings
    WHERE id = 1;

    v_min_price           := coalesce(v_min_price, 50);
    v_max_price           := coalesce(v_max_price, 5000.00);
    v_max_orders_per_hour := coalesce(v_max_orders_per_hour, 5);
    v_default_rate        := coalesce(v_default_rate, 20.00);

    -- Abuse protection: Check order creation rate for this reader in the past hour
    SELECT pg_catalog.count(*) INTO v_recent_order_count
    FROM public.orders
    WHERE reader_id = v_caller_id
      AND created_at >= (pg_catalog.now() - interval '1 hour');

    IF v_recent_order_count >= v_max_orders_per_hour THEN
        RAISE EXCEPTION 'Order rate limit exceeded. You can create at most % orders per hour. Please complete or cancel your existing orders before placing new ones.', v_max_orders_per_hour;
    END IF;

    -- Fetch novel
    SELECT * INTO v_novel
    FROM public.novels
    WHERE id = p_novel_id;

    IF v_novel.id IS NULL THEN
        RAISE EXCEPTION 'Novel not found: %', p_novel_id;
    END IF;

    IF v_novel.status::text != 'published' THEN
        RAISE EXCEPTION 'Novel is not available for purchase (status: %).', v_novel.status;
    END IF;

    -- Defensive price validation: whole rupees, > 0, within [min, max]
    IF v_novel.price_pkr <= 0 OR v_novel.price_pkr < v_min_price OR v_novel.price_pkr > v_max_price THEN
        RAISE EXCEPTION 'Novel price (PKR %) is invalid or outside allowable limits (PKR % to PKR %). Orders cannot be created.',
            v_novel.price_pkr, v_min_price, v_max_price;
    END IF;

    -- Self-purchase check: Writer cannot purchase their own novel
    IF v_novel.writer_id = v_caller_id THEN
        RAISE EXCEPTION 'Authors cannot purchase their own novels.';
    END IF;

    -- Fetch writer profile
    SELECT * INTO v_writer
    FROM public.writer_profiles
    WHERE id = v_novel.writer_id;

    IF v_writer.id IS NULL OR v_writer.status::text != 'approved' THEN
        RAISE EXCEPTION 'Writer is currently not eligible to receive orders.';
    END IF;

    IF v_writer.is_orders_paused_for_commission THEN
        RAISE EXCEPTION 'Orders for this author are currently paused due to accrued platform fee limit.';
    END IF;

    -- Check if reader already owns an active entitlement
    IF EXISTS (
        SELECT 1 FROM public.purchase_entitlements
        WHERE reader_id = v_caller_id
          AND novel_id = p_novel_id
          AND is_revoked = false
    ) THEN
        RAISE EXCEPTION 'You already hold an active purchase entitlement for this novel.';
    END IF;

    -- Check if reader already has an open, rejected, or disputed order for this novel
    IF EXISTS (
        SELECT 1 FROM public.orders
        WHERE reader_id = v_caller_id
          AND novel_id = p_novel_id
          AND status::text IN ('pending_payment', 'payment_submitted', 'rejected', 'disputed')
    ) THEN
        RAISE EXCEPTION 'An active, rejected, or disputed order for this novel already exists in your account. Please resolve your existing order before placing a new one.';
    END IF;

    -- Fetch and validate writer payment method
    SELECT * INTO v_method
    FROM public.writer_payment_methods
    WHERE id = p_payment_method_id
      AND writer_id = v_novel.writer_id
      AND is_active = true;

    IF v_method.id IS NULL THEN
        RAISE EXCEPTION 'Selected payment method is invalid or inactive.';
    END IF;

    -- Snapshot recipient instructions
    v_instructions := pg_catalog.jsonb_build_object(
        'payment_method_id', v_method.id,
        'method_type', v_method.method_type,
        'account_title', v_method.account_title,
        'account_number_or_iban', v_method.account_number_or_iban,
        'bank_name', v_method.bank_name,
        'instructions_note', v_method.instructions_note
    );

    -- Authoritative rate calculation
    v_applied_rate := coalesce(v_writer.custom_commission_rate, v_default_rate);

    -- Round platform fee and writer share
    v_commission_pkr   := pg_catalog.round((v_novel.price_pkr * v_applied_rate / 100.0), 2);
    v_writer_share_pkr := v_novel.price_pkr - v_commission_pkr;

    -- Generate unique human-readable order number
    v_order_number := 'ORD-' || pg_catalog.to_char(pg_catalog.now(), 'YYYYMMDD') || '-' || pg_catalog.upper(pg_catalog.substring(pg_catalog.replace(extensions.gen_random_uuid()::text, '-', ''), 1, 8));

    -- Insert order
    INSERT INTO public.orders (
        order_number,
        reader_id,
        writer_id,
        novel_id,
        novel_title_snapshot,
        amount_pkr,
        currency,
        selected_payment_method_id,
        payment_instructions_snapshot,
        applied_commission_rate,
        calculated_commission_pkr,
        calculated_writer_share_pkr,
        status,
        created_at,
        updated_at
    ) VALUES (
        v_order_number,
        v_caller_id,
        v_novel.writer_id,
        p_novel_id,
        coalesce(v_novel.title_urdu, v_novel.title_english),
        v_novel.price_pkr,
        'PKR',
        v_method.id,
        v_instructions,
        v_applied_rate,
        v_commission_pkr,
        v_writer_share_pkr,
        'pending_payment',
        pg_catalog.now(),
        pg_catalog.now()
    )
    RETURNING id INTO v_order_id;

    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'reader',
        'CREATE_ORDER',
        'orders',
        v_order_id::text,
        NULL,
        pg_catalog.jsonb_build_object(
            'order_number', v_order_number,
            'amount_pkr', v_novel.price_pkr,
            'novel_id', v_novel.id,
            'writer_id', v_novel.writer_id
        ),
        pg_catalog.now()
    );

    RETURN pg_catalog.jsonb_build_object(
        'order_id', v_order_id,
        'order_number', v_order_number,
        'status', 'pending_payment',
        'amount_pkr', v_novel.price_pkr,
        'instructions', v_instructions
    );
END;
$$;

REVOKE ALL ON FUNCTION public.create_order(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_order(uuid, uuid) TO authenticated;

-- ------------------------------------------------------------------------------
-- 5. get_platform_payment_instructions
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_platform_payment_instructions()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_has_open_invoice boolean := false;
    v_methods jsonb;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF public.is_admin() THEN
        v_has_open_invoice := true;
    ELSE
        SELECT EXISTS (
            SELECT 1 FROM public.commission_invoices
            WHERE writer_id = v_caller_id
              AND status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
        ) INTO v_has_open_invoice;
    END IF;

    IF NOT v_has_open_invoice THEN
        RAISE EXCEPTION 'Platform payment instructions are accessible only to writers with an active platform fee invoice.';
    END IF;

    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', id,
                'method_type', method_type,
                'account_title', account_title,
                'account_number_or_iban', account_number_or_iban,
                'bank_name', bank_name,
                'instructions_note', instructions_note
            )
            ORDER BY created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_methods
    FROM public.platform_payment_methods
    WHERE is_active = true;

    RETURN v_methods;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_platform_payment_instructions() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_platform_payment_instructions() TO authenticated;

-- ------------------------------------------------------------------------------
-- 6. preview_commission_invoice
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.preview_commission_invoice(
    p_writer_id uuid,
    p_period_start timestamptz,
    p_period_end timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_lines jsonb;
    v_sales_count integer := 0;
    v_refunds_count integer := 0;
    v_total_gross numeric(12,2) := 0.00;
    v_total_commission numeric(12,2) := 0.00;
    v_total_net numeric(12,2) := 0.00;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can preview platform fee invoices.';
    END IF;

    IF p_period_end <= p_period_start THEN
        RAISE EXCEPTION 'Period end date must be after period start date.';
    END IF;

    -- Aggregate uninvoiced ledger rows
    SELECT
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'ledger_entry_id', l.id,
                    'order_id', l.order_id,
                    'order_number', o.order_number,
                    'novel_title', coalesce(o.novel_title_snapshot, n.title_english, n.title_urdu, 'Manual Adjustment'),
                    'entry_type', l.entry_type,
                    'gross_amount_pkr', l.gross_amount_pkr,
                    'commission_rate', l.commission_rate,
                    'platform_commission_pkr', l.platform_commission_pkr,
                    'writer_net_pkr', l.writer_net_pkr,
                    'created_at', l.created_at
                )
                ORDER BY l.created_at ASC
            ),
            '[]'::jsonb
        ),
        count(CASE WHEN l.entry_type = 'sale_verified' THEN 1 END),
        count(CASE WHEN l.entry_type IN ('refund_adjustment', 'manual_correction') THEN 1 END),
        coalesce(sum(l.gross_amount_pkr), 0.00),
        coalesce(sum(l.platform_commission_pkr), 0.00),
        coalesce(sum(l.writer_net_pkr), 0.00)
    INTO v_lines, v_sales_count, v_refunds_count, v_total_gross, v_total_commission, v_total_net
    FROM public.sales_ledger l
    LEFT JOIN public.orders o ON o.id = l.order_id
    LEFT JOIN public.novels n ON n.id = l.novel_id
    WHERE l.writer_id = p_writer_id
      AND l.created_at >= p_period_start
      AND l.created_at <= p_period_end
      AND NOT EXISTS (
          SELECT 1
          FROM public.commission_invoice_lines cil
          WHERE cil.ledger_entry_id = l.id
            AND cil.is_voided = false
      );

    RETURN jsonb_build_object(
        'writer_id', p_writer_id,
        'period_start', p_period_start,
        'period_end', p_period_end,
        'sales_count', v_sales_count,
        'refunds_count', v_refunds_count,
        'total_entries_count', v_sales_count + v_refunds_count,
        'total_gross_pkr', v_total_gross,
        'total_commission_owed_pkr', v_total_commission,
        'total_writer_net_pkr', v_total_net,
        'can_generate_invoice', (v_total_commission > 0),
        'lines', v_lines
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.preview_commission_invoice(uuid, timestamptz, timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.preview_commission_invoice(uuid, timestamptz, timestamptz) TO authenticated;

-- ------------------------------------------------------------------------------
-- 7. generate_commission_invoice
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.generate_commission_invoice(
    p_writer_id uuid,
    p_period_start timestamptz,
    p_period_end timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice_id uuid;
    v_invoice_num text;
    v_due_days integer;
    v_due_date timestamptz;
    v_total_gross numeric(12,2) := 0.00;
    v_total_comm numeric(12,2) := 0.00;
    v_sales_count integer := 0;
    v_entries_count integer := 0;
    r_entry record;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can generate platform fee invoices.';
    END IF;

    IF p_period_end <= p_period_start THEN
        RAISE EXCEPTION 'Period end date must be after period start date.';
    END IF;

    SELECT coalesce(invoice_due_days, 7) INTO v_due_days
    FROM public.platform_settings
    WHERE id = 1;

    v_due_date := pg_catalog.now() + (v_due_days || ' days')::interval;

    -- Aggregate eligible ledger entries that are uninvoiced
    SELECT
        pg_catalog.count(*),
        pg_catalog.count(CASE WHEN entry_type = 'sale_verified' THEN 1 END),
        coalesce(pg_catalog.sum(gross_amount_pkr), 0.00),
        coalesce(pg_catalog.sum(platform_commission_pkr), 0.00)
    INTO v_entries_count, v_sales_count, v_total_gross, v_total_comm
    FROM public.sales_ledger l
    WHERE l.writer_id = p_writer_id
      AND l.created_at >= p_period_start
      AND l.created_at <= p_period_end
      AND NOT EXISTS (
          SELECT 1 FROM public.commission_invoice_lines cil
          WHERE cil.ledger_entry_id = l.id
            AND cil.is_voided = false
      );

    IF v_entries_count = 0 THEN
        RAISE EXCEPTION 'No uninvoiced ledger entries found for this author in the chosen period.';
    END IF;

    IF v_total_comm <= 0 THEN
        RAISE EXCEPTION 'Net platform fee for this billing period is PKR % (must be strictly positive to bill author; refunds/adjustments offset sales).', v_total_comm;
    END IF;

    -- Generate invoice number: INV-YYYYMM-XXXXXX
    v_invoice_num := 'INV-' || pg_catalog.to_char(p_period_end AT TIME ZONE 'Asia/Karachi', 'YYYYMM') || '-' || pg_catalog.upper(pg_catalog.substring(pg_catalog.replace(gen_random_uuid()::text, '-', ''), 1, 6));

    -- Insert commission invoice
    INSERT INTO public.commission_invoices (
        invoice_number,
        writer_id,
        period_start,
        period_end,
        total_sales_count,
        total_gross_pkr,
        total_commission_owed_pkr,
        amount_settled_pkr,
        status,
        due_date,
        created_at
    ) VALUES (
        v_invoice_num,
        p_writer_id,
        p_period_start,
        p_period_end,
        v_sales_count,
        v_total_gross,
        v_total_comm,
        0.00,
        'invoiced',
        v_due_date,
        pg_catalog.now()
    )
    RETURNING id INTO v_invoice_id;

    -- Insert invoice lines mapping each eligible ledger entry to this invoice
    FOR r_entry IN (
        SELECT l.id AS ledger_id, l.platform_commission_pkr
        FROM public.sales_ledger l
        WHERE l.writer_id = p_writer_id
          AND l.created_at >= p_period_start
          AND l.created_at <= p_period_end
          AND NOT EXISTS (
              SELECT 1 FROM public.commission_invoice_lines cil
              WHERE cil.ledger_entry_id = l.id
                AND cil.is_voided = false
          )
    ) LOOP
        INSERT INTO public.commission_invoice_lines (
            invoice_id,
            ledger_entry_id,
            commission_pkr,
            is_voided,
            created_at
        ) VALUES (
            v_invoice_id,
            r_entry.ledger_id,
            r_entry.platform_commission_pkr,
            false,
            pg_catalog.now()
        );
    END LOOP;

    -- Notify writer
    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        body,
        link,
        entity_refs,
        is_read,
        created_at
    ) VALUES (
        p_writer_id,
        'invoice_generated',
        'پلیٹ فارم فیس انوائس جاری ہو گئی (Platform Fee Invoice Issued)',
        'انوائس نمبر ' || v_invoice_num || ' جاری ہو چکی ہے۔ واجب الادا پلیٹ فارم فیس: PKR ' || v_total_comm || '۔ آخری تاریخ: ' || pg_catalog.to_char(v_due_date AT TIME ZONE 'Asia/Karachi', 'DD-MM-YYYY') || '۔',
        'انوائس نمبر ' || v_invoice_num || ' جاری ہو چکی ہے۔ واجب الادا پلیٹ فارم فیس: PKR ' || v_total_comm || '۔',
        '/writer/commission/' || v_invoice_id,
        pg_catalog.jsonb_build_object('invoice_id', v_invoice_id, 'invoice_number', v_invoice_num, 'amount_pkr', v_total_comm),
        false,
        pg_catalog.now()
    );

    -- Audit log
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'GENERATE_COMMISSION_INVOICE',
        'commission_invoices',
        v_invoice_id::text,
        NULL,
        pg_catalog.jsonb_build_object(
            'invoice_id', v_invoice_id,
            'invoice_number', v_invoice_num,
            'writer_id', p_writer_id,
            'total_gross_pkr', v_total_gross,
            'total_commission_owed_pkr', v_total_comm,
            'sales_count', v_sales_count,
            'due_date', v_due_date
        ),
        pg_catalog.now()
    );

    RETURN pg_catalog.jsonb_build_object(
        'success', true,
        'invoice_id', v_invoice_id,
        'invoice_number', v_invoice_num,
        'total_gross_pkr', v_total_gross,
        'total_commission_owed_pkr', v_total_comm,
        'sales_count', v_sales_count,
        'due_date', v_due_date
    );
END;
$$;

REVOKE ALL ON FUNCTION public.generate_commission_invoice(uuid, timestamptz, timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.generate_commission_invoice(uuid, timestamptz, timestamptz) TO authenticated;

-- ------------------------------------------------------------------------------
-- 8. void_commission_invoice
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.void_commission_invoice(
    p_invoice_id uuid,
    p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice record;
    v_payments_count integer := 0;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can void platform fee invoices.';
    END IF;

    IF p_reason IS NULL OR trim(p_reason) = '' THEN
        RAISE EXCEPTION 'A justification reason is required to void an invoice.';
    END IF;

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = p_invoice_id
    FOR UPDATE;

    IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee invoice not found: %', p_invoice_id;
    END IF;

    IF v_invoice.status = 'void' THEN
        RAISE EXCEPTION 'Invoice is already voided.';
    END IF;

    SELECT count(*) INTO v_payments_count
    FROM public.commission_payments
    WHERE invoice_id = p_invoice_id;

    IF v_payments_count > 0 OR v_invoice.amount_settled_pkr > 0 THEN
        RAISE EXCEPTION 'Cannot void invoice: Confirmed payment settlements (PKR %) already exist against this invoice. Issue a manual correction instead.', v_invoice.amount_settled_pkr;
    END IF;

    -- Update invoice to void
    UPDATE public.commission_invoices
    SET status = 'void',
        voided_at = now(),
        voided_by = v_caller_id,
        void_reason = trim(p_reason)
    WHERE id = p_invoice_id;

    -- Mark lines voided so the underlying sales ledger entries can be re-invoiced
    UPDATE public.commission_invoice_lines
    SET is_voided = true
    WHERE invoice_id = p_invoice_id;

    -- Reject any pending writer reports on this voided invoice
    UPDATE public.commission_payment_reports
    SET status = 'rejected',
        admin_note = 'Invoice voided: ' || trim(p_reason),
        reviewed_by = v_caller_id,
        reviewed_at = now()
    WHERE invoice_id = p_invoice_id
      AND status = 'pending';

    -- Audit log
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'VOID_COMMISSION_INVOICE',
        'commission_invoices',
        p_invoice_id::text,
        jsonb_build_object('status', v_invoice.status),
        jsonb_build_object('status', 'void', 'reason', trim(p_reason)),
        now()
    );

    RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.void_commission_invoice(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.void_commission_invoice(uuid, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 9. report_commission_payment
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.report_commission_payment(
    p_invoice_id uuid,
    p_amount_pkr numeric,
    p_tid text,
    p_screenshot_path text,
    p_writer_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice record;
    v_clean_tid text;
    v_norm_tid text;
    v_is_dup boolean := false;
    v_report_id uuid;
    v_prefix text;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF p_amount_pkr <= 0 THEN
        RAISE EXCEPTION 'Settlement payment amount must be positive. Provided: %', p_amount_pkr;
    END IF;

    -- Path traversal and invoice-folder isolation
    v_prefix := p_invoice_id::text || '/';
    IF p_screenshot_path IS NULL OR NOT (p_screenshot_path LIKE v_prefix || '%') OR p_screenshot_path LIKE '%..%' THEN
        RAISE EXCEPTION 'Invalid screenshot path: Must start with % and contain no path traversal.', v_prefix;
    END IF;

    -- TID Format Validation (6 - 40 characters)
    v_clean_tid := trim(p_tid);
    IF v_clean_tid IS NULL OR length(v_clean_tid) < 6 OR length(v_clean_tid) > 40 OR v_clean_tid !~ '^[a-zA-Z0-9_\-]+$' THEN
        RAISE EXCEPTION 'Invalid transaction reference (TID): Must be 6 to 40 alphanumeric characters, hyphens or underscores.';
    END IF;

    v_norm_tid := upper(regexp_replace(v_clean_tid, '[^a-zA-Z0-9]', '', 'g'));

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = p_invoice_id
    FOR UPDATE;

    IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee invoice not found: %', p_invoice_id;
    END IF;

    IF v_invoice.writer_id != v_caller_id AND NOT public.is_admin() THEN
        RAISE EXCEPTION 'Unauthorized: Only the invoiced author can report settlement.';
    END IF;

    IF v_invoice.status NOT IN ('invoiced', 'open', 'payment_reported', 'partially_paid') THEN
        RAISE EXCEPTION 'Payment cannot be reported for invoice in status: %', v_invoice.status;
    END IF;

    -- Check for duplicate TID across past commission reports
    SELECT EXISTS (
        SELECT 1 FROM public.commission_payment_reports
        WHERE normalized_tid = v_norm_tid
          AND invoice_id != p_invoice_id
    ) INTO v_is_dup;

    -- Insert into commission_payment_reports
    INSERT INTO public.commission_payment_reports (
        invoice_id,
        writer_id,
        amount_pkr,
        transaction_reference,
        normalized_tid,
        screenshot_path,
        writer_note,
        status,
        is_duplicate_tid,
        created_at
    ) VALUES (
        p_invoice_id,
        v_invoice.writer_id,
        p_amount_pkr,
        v_clean_tid,
        v_norm_tid,
        p_screenshot_path,
        nullif(trim(p_writer_note), ''),
        'pending',
        v_is_dup,
        now()
    )
    RETURNING id INTO v_report_id;

    -- Transition invoice status to payment_reported (balances unchanged until admin confirms)
    UPDATE public.commission_invoices
    SET status = 'payment_reported'
    WHERE id = p_invoice_id;

    -- Audit log
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'writer',
        'REPORT_COMMISSION_PAYMENT',
        'commission_payment_reports',
        v_report_id::text,
        jsonb_build_object('invoice_status', v_invoice.status),
        jsonb_build_object(
            'invoice_id', p_invoice_id,
            'amount_pkr', p_amount_pkr,
            'tid', v_clean_tid,
            'is_duplicate_tid', v_is_dup
        ),
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'report_id', v_report_id,
        'status', 'pending',
        'is_duplicate_tid', v_is_dup
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.report_commission_payment(uuid, numeric, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_commission_payment(uuid, numeric, text, text, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 10. confirm_commission_settlement
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.confirm_commission_settlement(
    p_invoice_id uuid,
    p_amount_pkr numeric,
    p_report_id uuid DEFAULT NULL,
    p_admin_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice record;
    v_report record;
    v_payment_id uuid;
    v_remaining numeric(12,2);
    v_new_settled numeric(12,2);
    v_new_status public.commission_invoice_status;
    v_new_unpaid numeric(12,2);
    v_is_paused boolean;
    v_tid text := 'ADMIN-CONFIRMED';
    v_proof text := NULL;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can confirm platform fee settlements.';
    END IF;

    IF p_amount_pkr <= 0 THEN
        RAISE EXCEPTION 'Settlement confirmation amount must be positive. Provided: %', p_amount_pkr;
    END IF;

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = p_invoice_id
    FOR UPDATE;

    IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee invoice not found: %', p_invoice_id;
    END IF;

    IF v_invoice.status = 'void' THEN
        RAISE EXCEPTION 'Cannot confirm settlement on a voided invoice.';
    END IF;

    -- Refuse double confirmation on already settled invoice
    IF v_invoice.status = 'settled' OR v_invoice.amount_settled_pkr >= v_invoice.total_commission_owed_pkr THEN
        RAISE EXCEPTION 'Invoice % is already fully settled.', v_invoice.invoice_number;
    END IF;

    -- Refuse overpayment
    v_remaining := v_invoice.total_commission_owed_pkr - v_invoice.amount_settled_pkr;
    IF p_amount_pkr > v_remaining THEN
        RAISE EXCEPTION 'Settlement amount (PKR %) exceeds remaining unpaid invoice balance of PKR %.', p_amount_pkr, v_remaining;
    END IF;

    -- Validate and link payment report if supplied
    IF p_report_id IS NOT NULL THEN
        SELECT * INTO v_report
        FROM public.commission_payment_reports
        WHERE id = p_report_id AND invoice_id = p_invoice_id
        FOR UPDATE;

        IF v_report.id IS NULL THEN
            RAISE EXCEPTION 'Platform fee payment report % not found for invoice %.', p_report_id, p_invoice_id;
        END IF;

        IF v_report.status != 'pending' THEN
            RAISE EXCEPTION 'Platform fee payment report % has already been reviewed (current status: %).', p_report_id, v_report.status;
        END IF;

        v_tid := v_report.transaction_reference;
        v_proof := v_report.screenshot_path;

        UPDATE public.commission_payment_reports
        SET status = 'confirmed',
            admin_note = nullif(pg_catalog.btrim(p_admin_note), ''),
            reviewed_by = v_caller_id,
            reviewed_at = pg_catalog.now()
        WHERE id = p_report_id;
    END IF;

    v_new_settled := v_invoice.amount_settled_pkr + p_amount_pkr;
    IF v_new_settled >= v_invoice.total_commission_owed_pkr THEN
        v_new_status := 'settled'::public.commission_invoice_status;
    ELSE
        v_new_status := 'partially_paid'::public.commission_invoice_status;
    END IF;

    -- Update invoice settlement figures and timestamps
    UPDATE public.commission_invoices
    SET amount_settled_pkr = v_new_settled,
        status = v_new_status,
        settled_by_admin_id = v_caller_id,
        settled_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    WHERE id = p_invoice_id;

    -- Insert into immutable commission_payments ledger
    INSERT INTO public.commission_payments (
        invoice_id,
        writer_id,
        amount_pkr,
        transaction_reference,
        screenshot_url,
        confirmed_by_admin_id,
        confirmed_at,
        notes,
        created_at
    ) VALUES (
        p_invoice_id,
        v_invoice.writer_id,
        p_amount_pkr,
        v_tid,
        v_proof,
        v_caller_id,
        pg_catalog.now(),
        coalesce(nullif(pg_catalog.btrim(p_admin_note), ''), 'Platform fee payment confirmed by admin.'),
        pg_catalog.now()
    )
    RETURNING id INTO v_payment_id;

    -- Recalculate author commission balance and automatic pause status
    v_new_unpaid := public.reconcile_writer_unpaid_commission(v_invoice.writer_id);

    SELECT is_orders_paused_for_commission INTO v_is_paused
    FROM public.writer_profiles
    WHERE id = v_invoice.writer_id;

    -- Notify writer of verified settlement
    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        body,
        link,
        entity_refs,
        is_read,
        created_at
    ) VALUES (
        v_invoice.writer_id,
        'commission_settled',
        'پلیٹ فارم فیس ادائیگی کی تصدیق (Platform Fee Payment Confirmed)',
        'آپ کی پلیٹ فارم فیس ادائیگی بمبلغ PKR ' || p_amount_pkr || ' کی تصدیق ہو چکی ہے۔ انوائس: ' || v_invoice.invoice_number,
        'آپ کی پلیٹ فارم فیس کی ادائیگی قبول کر لی گئی ہے۔ نئی واجب الادا پلیٹ فارم فیس: PKR ' || v_new_unpaid,
        '/writer/commission/' || p_invoice_id,
        pg_catalog.jsonb_build_object(
            'invoice_id', p_invoice_id,
            'payment_id', v_payment_id,
            'amount_pkr', p_amount_pkr,
            'remaining_balance', v_new_unpaid
        ),
        false,
        pg_catalog.now()
    );

    -- Record in immutable audit logs
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'CONFIRM_COMMISSION_SETTLEMENT',
        'commission_invoices',
        p_invoice_id::text,
        pg_catalog.jsonb_build_object(
            'amount_settled_pkr', v_invoice.amount_settled_pkr,
            'status', v_invoice.status
        ),
        pg_catalog.jsonb_build_object(
            'amount_settled_pkr', v_new_settled,
            'status', v_new_status,
            'payment_id', v_payment_id,
            'amount_pkr', p_amount_pkr,
            'new_unpaid_commission', v_new_unpaid,
            'is_orders_paused_for_commission', v_is_paused
        ),
        pg_catalog.now()
    );

    RETURN pg_catalog.jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'payment_id', v_payment_id,
        'amount_confirmed_pkr', p_amount_pkr,
        'amount_settled_pkr', v_new_settled,
        'total_settled_pkr', v_new_settled,
        'invoice_status', v_new_status,
        'writer_id', v_invoice.writer_id,
        'writer_unpaid_balance_pkr', v_new_unpaid,
        'new_unpaid_commission', v_new_unpaid,
        'is_orders_paused', v_is_paused,
        'is_orders_paused_for_commission', v_is_paused
    );
END;
$$;

REVOKE ALL ON FUNCTION public.confirm_commission_settlement(uuid, numeric, uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirm_commission_settlement(uuid, numeric, uuid, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 11. reject_commission_report
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reject_commission_report(
    p_report_id uuid,
    p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_report record;
    v_invoice record;
    v_has_pending boolean;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can reject platform fee payment reports.';
    END IF;

    IF p_reason IS NULL OR trim(p_reason) = '' THEN
        RAISE EXCEPTION 'A justification reason is required to reject a payment report.';
    END IF;

    SELECT * INTO v_report
    FROM public.commission_payment_reports
    WHERE id = p_report_id
    FOR UPDATE;

    IF v_report.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee payment report not found: %', p_report_id;
    END IF;

    IF v_report.status != 'pending' THEN
        RAISE EXCEPTION 'Only pending payment reports can be rejected (current status: %).', v_report.status;
    END IF;

    UPDATE public.commission_payment_reports
    SET status = 'rejected',
        admin_note = trim(p_reason),
        reviewed_by = v_caller_id,
        reviewed_at = now()
    WHERE id = p_report_id;

    -- Check if any other pending reports exist for this invoice
    SELECT EXISTS (
        SELECT 1 FROM public.commission_payment_reports
        WHERE invoice_id = v_report.invoice_id
          AND status = 'pending'
    ) INTO v_has_pending;

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = v_report.invoice_id;

    -- If no more pending reports, revert invoice status back to invoiced (or partially_paid)
    IF NOT v_has_pending AND v_invoice.status = 'payment_reported' THEN
        UPDATE public.commission_invoices
        SET status = CASE
            WHEN amount_settled_pkr > 0 THEN 'partially_paid'::public.commission_invoice_status
            ELSE 'invoiced'::public.commission_invoice_status
        END
        WHERE id = v_report.invoice_id;
    END IF;

    -- Notify writer
    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        body,
        link,
        entity_refs,
        is_read,
        created_at
    ) VALUES (
        v_report.writer_id,
        'commission_report_rejected',
        'پلیٹ فارم فیس رپورٹ مسترد (Platform Fee Payment Report Rejected)',
        'انوائس کے لیے آپ کی جمع کردہ پلیٹ فارم فیس کی رسید مسترد کر دی گئی ہے۔ وجہ: ' || trim(p_reason),
        'پلیٹ فارم فیس کی رسید مسترد کر دی گئی ہے۔ وجہ: ' || trim(p_reason),
        '/writer/commission/' || v_report.invoice_id,
        jsonb_build_object('report_id', p_report_id, 'invoice_id', v_report.invoice_id, 'reason', trim(p_reason)),
        false,
        now()
    );

    -- Audit log
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'REJECT_COMMISSION_REPORT',
        'commission_payment_reports',
        p_report_id::text,
        jsonb_build_object('status', 'pending'),
        jsonb_build_object('status', 'rejected', 'reason', trim(p_reason)),
        now()
    );

    RETURN jsonb_build_object('success', true, 'report_id', p_report_id);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reject_commission_report(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reject_commission_report(uuid, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 12. record_commission_adjustment
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.record_commission_adjustment(
    p_writer_id uuid,
    p_amount_pkr numeric,
    p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_adjustment_id uuid;
    v_new_unpaid numeric(12,2);
    v_is_paused boolean;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can record platform fee adjustments.';
    END IF;

    IF p_reason IS NULL OR trim(p_reason) = '' THEN
        RAISE EXCEPTION 'A justification reason is required for platform fee adjustments.';
    END IF;

    IF p_amount_pkr = 0 THEN
        RAISE EXCEPTION 'Adjustment amount cannot be zero.';
    END IF;

    -- Insert append-only ledger row maintaining: gross = platform_commission + writer_net
    INSERT INTO public.sales_ledger (
        writer_id,
        entry_type,
        gross_amount_pkr,
        commission_rate,
        platform_commission_pkr,
        writer_net_pkr,
        notes,
        created_at
    ) VALUES (
        p_writer_id,
        'manual_correction',
        0.00,
        0.00,
        p_amount_pkr,
        -1.00 * p_amount_pkr,
        'Manual Platform Fee Adjustment: ' || trim(p_reason),
        now()
    )
    RETURNING id INTO v_adjustment_id;

    -- Reconcile author profile
    v_new_unpaid := public.reconcile_writer_unpaid_commission(p_writer_id);

    SELECT is_orders_paused_for_commission INTO v_is_paused
    FROM public.writer_profiles
    WHERE id = p_writer_id;

    -- Audit log
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action_type,
        entity_type,
        entity_id,
        previous_state,
        new_state,
        created_at
    ) VALUES (
        v_caller_id,
        'admin',
        'RECORD_COMMISSION_ADJUSTMENT',
        'sales_ledger',
        v_adjustment_id::text,
        NULL,
        jsonb_build_object(
            'writer_id', p_writer_id,
            'adjustment_amount_pkr', p_amount_pkr,
            'reason', trim(p_reason),
            'new_unpaid_balance_pkr', v_new_unpaid,
            'is_orders_paused', v_is_paused
        ),
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'ledger_id', v_adjustment_id,
        'adjustment_amount_pkr', p_amount_pkr,
        'new_unpaid_balance_pkr', v_new_unpaid,
        'is_orders_paused', v_is_paused
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.record_commission_adjustment(uuid, numeric, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_commission_adjustment(uuid, numeric, text) TO authenticated;

-- ------------------------------------------------------------------------------
-- 13. apply_overdue_rules
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.apply_overdue_rules(p_apply boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_grace_days integer;
    v_overdue_list jsonb;
    v_affected_writers jsonb;
    r_writer record;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can inspect or apply overdue rules.';
    END IF;

    SELECT coalesce(overdue_grace_days, 3) INTO v_grace_days
    FROM public.platform_settings
    WHERE id = 1;

    -- Find non-voided, unsettled invoices past due_date + grace days
    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'invoice_id', ci.id,
                'invoice_number', ci.invoice_number,
                'writer_id', ci.writer_id,
                'writer_pen_name', wp.pen_name_english,
                'total_commission_owed_pkr', ci.total_commission_owed_pkr,
                'amount_settled_pkr', ci.amount_settled_pkr,
                'remaining_owed_pkr', ci.total_commission_owed_pkr - ci.amount_settled_pkr,
                'due_date', ci.due_date,
                'grace_cutoff', ci.due_date + (v_grace_days || ' days')::interval,
                'days_past_grace', extract(day from (now() - (ci.due_date + (v_grace_days || ' days')::interval)))::integer,
                'status', ci.status
            )
            ORDER BY ci.due_date ASC
        ),
        '[]'::jsonb
    )
    INTO v_overdue_list
    FROM public.commission_invoices ci
    JOIN public.writer_profiles wp ON wp.id = ci.writer_id
    WHERE ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
      AND ci.due_date IS NOT NULL
      AND now() > (ci.due_date + (v_grace_days || ' days')::interval);

    -- If admin confirms application, pause new orders for all writers with overdue invoices
    IF p_apply THEN
        FOR r_writer IN (
            SELECT DISTINCT ci.writer_id
            FROM public.commission_invoices ci
            WHERE ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
              AND ci.due_date IS NOT NULL
              AND now() > (ci.due_date + (v_grace_days || ' days')::interval)
        ) LOOP
            UPDATE public.writer_profiles
            SET is_orders_paused_for_commission = true,
                updated_at = now()
            WHERE id = r_writer.writer_id;

            INSERT INTO public.notifications (
                user_id,
                type,
                title,
                message,
                body,
                link,
                entity_refs,
                is_read,
                created_at
            ) VALUES (
                r_writer.writer_id,
                'invoice_overdue_orders_paused',
                'انوائس کی عدم ادائیگی: نئے آرڈرز روک دیے گئے (Orders Paused - Overdue Invoice)',
                'آپ کی پلیٹ فارم فیس انوائس مہلت کی مدت ختم ہونے کے بعد بھی واجب الادا ہے۔ نئے آرڈرز عارضی طور پر روک دیے گئے ہیں۔',
                'انوائس کی مدت ختم ہونے پر نئے آرڈرز معطل کر دیے گئے ہیں۔',
                '/writer/commission',
                jsonb_build_object('reason', 'overdue_invoice'),
                false,
                now()
            );

            INSERT INTO public.audit_logs (
                actor_id,
                actor_role,
                action_type,
                entity_type,
                entity_id,
                previous_state,
                new_state,
                created_at
            ) VALUES (
                v_caller_id,
                'admin',
                'APPLY_OVERDUE_RULES_PAUSE',
                'writer_profiles',
                r_writer.writer_id::text,
                jsonb_build_object('is_orders_paused_for_commission', false),
                jsonb_build_object('is_orders_paused_for_commission', true, 'reason', 'overdue_grace_exceeded'),
                now()
            );
        END LOOP;
    END IF;

    RETURN jsonb_build_object(
        'applied', p_apply,
        'grace_days', v_grace_days,
        'overdue_invoices_count', jsonb_array_length(v_overdue_list),
        'overdue_invoices', v_overdue_list
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.apply_overdue_rules(boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.apply_overdue_rules(boolean) TO authenticated;

-- ------------------------------------------------------------------------------
-- 14. get_my_invoice
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_my_invoice(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice record;
    v_lines jsonb;
    v_payments jsonb;
    v_reports jsonb;
    v_grace_days integer;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    SELECT coalesce(overdue_grace_days, 3) INTO v_grace_days
    FROM public.platform_settings
    WHERE id = 1;

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = p_invoice_id;

    IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee invoice not found: %', p_invoice_id;
    END IF;

    IF v_invoice.writer_id != v_caller_id AND NOT public.is_admin() THEN
        RAISE EXCEPTION 'Unauthorized: You can only view your own platform fee invoices.';
    END IF;

    -- Lines (Sales ledger details)
    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', cil.id,
                'ledger_entry_id', cil.ledger_entry_id,
                'order_number', o.order_number,
                'novel_title', coalesce(o.novel_title_snapshot, n.title_english, n.title_urdu, 'Manual Adjustment'),
                'gross_amount_pkr', l.gross_amount_pkr,
                'commission_rate', l.commission_rate,
                'commission_pkr', cil.commission_pkr,
                'created_at', l.created_at
            )
            ORDER BY l.created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_lines
    FROM public.commission_invoice_lines cil
    JOIN public.sales_ledger l ON l.id = cil.ledger_entry_id
    LEFT JOIN public.orders o ON o.id = l.order_id
    LEFT JOIN public.novels n ON n.id = l.novel_id
    WHERE cil.invoice_id = p_invoice_id
      AND cil.is_voided = false;

    -- Confirmed payments
    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', id,
                'amount_pkr', amount_pkr,
                'transaction_reference', transaction_reference,
                'confirmed_at', confirmed_at,
                'notes', notes
            )
            ORDER BY confirmed_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_payments
    FROM public.commission_payments
    WHERE invoice_id = p_invoice_id;

    -- Author payment reports
    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', id,
                'amount_pkr', amount_pkr,
                'transaction_reference', transaction_reference,
                'status', status,
                'admin_note', admin_note,
                'created_at', created_at,
                'reviewed_at', reviewed_at
            )
            ORDER BY created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_reports
    FROM public.commission_payment_reports
    WHERE invoice_id = p_invoice_id;

    RETURN jsonb_build_object(
        'id', v_invoice.id,
        'invoice_number', v_invoice.invoice_number,
        'period_start', v_invoice.period_start,
        'period_end', v_invoice.period_end,
        'total_sales_count', v_invoice.total_sales_count,
        'total_gross_pkr', v_invoice.total_gross_pkr,
        'total_commission_owed_pkr', v_invoice.total_commission_owed_pkr,
        'amount_settled_pkr', v_invoice.amount_settled_pkr,
        'remaining_owed_pkr', v_invoice.total_commission_owed_pkr - v_invoice.amount_settled_pkr,
        'status', v_invoice.status,
        'due_date', v_invoice.due_date,
        'is_overdue', (v_invoice.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid') AND v_invoice.due_date IS NOT NULL AND now() > (v_invoice.due_date + (v_grace_days || ' days')::interval)),
        'created_at', v_invoice.created_at,
        'lines', v_lines,
        'payments', v_payments,
        'reports', v_reports
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_my_invoice(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_my_invoice(uuid) TO authenticated;

-- ------------------------------------------------------------------------------
-- 15. admin_get_invoice
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_get_invoice(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_invoice record;
    v_writer record;
    v_lines jsonb;
    v_payments jsonb;
    v_reports jsonb;
    v_grace_days integer;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required.';
    END IF;

    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can inspect invoice details.';
    END IF;

    SELECT coalesce(overdue_grace_days, 3) INTO v_grace_days
    FROM public.platform_settings
    WHERE id = 1;

    SELECT * INTO v_invoice
    FROM public.commission_invoices
    WHERE id = p_invoice_id;

    IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Platform fee invoice not found: %', p_invoice_id;
    END IF;

    SELECT * INTO v_writer
    FROM public.writer_profiles
    WHERE id = v_invoice.writer_id;

    -- Lines (Sales ledger details)
    SELECT coalesce(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'id', cil.id,
                'ledger_entry_id', cil.ledger_entry_id,
                'order_number', o.order_number,
                'novel_title', coalesce(o.novel_title_snapshot, n.title_english, n.title_urdu, 'Manual Adjustment'),
                'gross_amount_pkr', l.gross_amount_pkr,
                'commission_rate', l.commission_rate,
                'commission_pkr', cil.commission_pkr,
                'created_at', l.created_at
            )
            ORDER BY l.created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_lines
    FROM public.commission_invoice_lines cil
    JOIN public.sales_ledger l ON l.id = cil.ledger_entry_id
    LEFT JOIN public.orders o ON o.id = l.order_id
    LEFT JOIN public.novels n ON n.id = l.novel_id
    WHERE cil.invoice_id = p_invoice_id
      AND cil.is_voided = false;

    -- Confirmed payments
    SELECT coalesce(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'id', id,
                'amount_pkr', amount_pkr,
                'transaction_reference', transaction_reference,
                'confirmed_at', confirmed_at,
                'notes', notes,
                'confirmed_by_admin_id', confirmed_by_admin_id
            )
            ORDER BY confirmed_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_payments
    FROM public.commission_payments
    WHERE invoice_id = p_invoice_id;

    -- Author payment reports
    SELECT coalesce(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'id', id,
                'amount_pkr', amount_pkr,
                'transaction_reference', transaction_reference,
                'screenshot_path', screenshot_path,
                'writer_note', writer_note,
                'status', status,
                'is_duplicate_tid', is_duplicate_tid,
                'admin_note', admin_note,
                'created_at', created_at,
                'reviewed_at', reviewed_at,
                'reviewed_by', reviewed_by
            )
            ORDER BY created_at ASC
        ),
        '[]'::jsonb
    )
    INTO v_reports
    FROM public.commission_payment_reports
    WHERE invoice_id = p_invoice_id;

    RETURN pg_catalog.jsonb_build_object(
        'id', v_invoice.id,
        'invoice_number', v_invoice.invoice_number,
        'writer_id', v_invoice.writer_id,
        'writer_pen_name', v_writer.pen_name_english,
        'writer_pen_name_urdu', v_writer.pen_name_urdu,
        'period_start', v_invoice.period_start,
        'period_end', v_invoice.period_end,
        'total_sales_count', v_invoice.total_sales_count,
        'total_gross_pkr', v_invoice.total_gross_pkr,
        'total_commission_owed_pkr', v_invoice.total_commission_owed_pkr,
        'amount_settled_pkr', v_invoice.amount_settled_pkr,
        'remaining_owed_pkr', v_invoice.total_commission_owed_pkr - v_invoice.amount_settled_pkr,
        'status', v_invoice.status,
        'due_date', v_invoice.due_date,
        'is_overdue', (
            v_invoice.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
            AND v_invoice.due_date IS NOT NULL
            AND pg_catalog.now() > (v_invoice.due_date + (v_grace_days || ' days')::interval)
        ),
        'voided_at', v_invoice.voided_at,
        'void_reason', v_invoice.void_reason,
        'created_at', v_invoice.created_at,
        'lines', v_lines,
        'payments', v_payments,
        'reports', v_reports
    );
END;
$$;

REVOKE ALL ON FUNCTION public.admin_get_invoice(uuid) FROM PUBLIC, anon;
