-- ------------------------------------------------------------------------------
-- 16. get_writer_unpaid_commission
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_writer_unpaid_commission(p_writer_id uuid)
RETURNS numeric(12,2)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_total_ledger_comm numeric(12,2);
    v_total_paid numeric(12,2);
BEGIN
    v_caller_id := auth.uid();

    -- Strict authorization check: If called from an API context, reject any cross-writer caller
    IF current_user IN ('authenticated', 'anon', 'authenticator') THEN
        IF v_caller_id IS NULL OR (v_caller_id != p_writer_id AND NOT public.is_admin()) THEN
            RAISE EXCEPTION 'Access denied: You can only inspect your own platform fee balance.';
        END IF;
    ELSIF v_caller_id IS NOT NULL THEN
        IF v_caller_id != p_writer_id AND NOT public.is_admin() THEN
            RAISE EXCEPTION 'Access denied: You can only inspect your own platform fee balance.';
        END IF;
    END IF;

    SELECT coalesce(pg_catalog.sum(platform_commission_pkr), 0.00)
    INTO v_total_ledger_comm
    FROM public.sales_ledger
    WHERE writer_id = p_writer_id;

    SELECT coalesce(pg_catalog.sum(amount_pkr), 0.00)
    INTO v_total_paid
    FROM public.commission_payments
    WHERE writer_id = p_writer_id;

    RETURN greatest(0.00, v_total_ledger_comm - v_total_paid);
END;
$$;

REVOKE ALL ON FUNCTION public.get_writer_unpaid_commission(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_writer_unpaid_commission(uuid) TO authenticated;

-- ------------------------------------------------------------------------------
-- 17. reconcile_writer_unpaid_commission
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reconcile_writer_unpaid_commission(p_writer_id uuid)
RETURNS numeric(12,2)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_actual_unpaid numeric(12,2);
    v_limit numeric(12,2);
    v_is_paused boolean;
    v_last_settlement timestamptz;
BEGIN
    v_caller_id := auth.uid();

    -- Strict authorization check: If called from an API context, reject any cross-writer caller
    IF current_user IN ('authenticated', 'anon', 'authenticator') THEN
        IF v_caller_id IS NULL OR (v_caller_id != p_writer_id AND NOT public.is_admin()) THEN
            RAISE EXCEPTION 'Access denied: You can only reconcile your own account.';
        END IF;
    ELSIF v_caller_id IS NOT NULL THEN
        IF v_caller_id != p_writer_id AND NOT public.is_admin() THEN
            RAISE EXCEPTION 'Access denied: You can only reconcile your own account.';
        END IF;
    END IF;

    v_actual_unpaid := public.get_writer_unpaid_commission(p_writer_id);

    SELECT unpaid_commission_limit INTO v_limit
    FROM public.writer_profiles
    WHERE id = p_writer_id;

    IF v_limit IS NULL OR v_limit <= 0 THEN
        v_limit := 5000.00;
    END IF;

    v_is_paused := (v_actual_unpaid >= v_limit);

    UPDATE public.writer_profiles
    SET current_unpaid_commission = v_actual_unpaid,
        is_orders_paused_for_commission = v_is_paused,
        updated_at = pg_catalog.now()
    WHERE id = p_writer_id;

    SELECT pg_catalog.max(confirmed_at) INTO v_last_settlement
    FROM public.commission_payments
    WHERE writer_id = p_writer_id;

    IF v_last_settlement IS NULL THEN
        v_last_settlement := '2000-01-01 00:00:00+00'::timestamptz;
    END IF;

    -- 80% Threshold Warning notification
    IF v_actual_unpaid >= (0.80 * v_limit) AND v_actual_unpaid < v_limit THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = p_writer_id
              AND type = 'commission_threshold_warning'
              AND created_at >= v_last_settlement
        ) THEN
            INSERT INTO public.notifications (
                user_id,
                type,
                title,
                message,
                body,
                link,
                entity_refs,
                is_read,
                created_at
            ) VALUES (
                p_writer_id,
                'commission_threshold_warning',
                'تنبہی پلیٹ فارم فیس حد (80% Platform Fee Threshold)',
                'آپ کی واجب الادا پلیٹ فارم فیس (PKR ' || v_actual_unpaid || ') حد (' || v_limit || ') کے 80 فیصد تک پہنچ چکی ہے۔ براہِ کرم معطلی سے بچنے کے لیے ادائیگی کریں۔',
                'آپ کی واجب الادا پلیٹ فارم فیس حد کے قریب پہنچ چکی ہے۔',
                '/writer/commission',
                pg_catalog.jsonb_build_object('unpaid', v_actual_unpaid, 'limit', v_limit),
                false,
                pg_catalog.now()
            );
        END IF;
    END IF;

    -- 100% Threshold Exceeded notification
    IF v_actual_unpaid >= v_limit THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = p_writer_id
              AND type = 'commission_limit_exceeded'
              AND created_at >= v_last_settlement
        ) THEN
            INSERT INTO public.notifications (
                user_id,
                type,
                title,
                message,
                body,
                link,
                entity_refs,
                is_read,
                created_at
            ) VALUES (
                p_writer_id,
                'commission_limit_exceeded',
                'ناولوں کے آرڈرز عارضی طور پر موقوف (Orders Paused)',
                'آپ کی واجب الادا پلیٹ فارم فیس (PKR ' || v_actual_unpaid || ') مقررہ حد (' || v_limit || ') سے تجاوز کر گئی ہے۔ نئے قارئین کے لیے آرڈرز موقوف کر دیے گئے ہیں۔',
                'پلیٹ فارم فیس کلیئر ہوتے ہی آپ کے ناولز کے آرڈرز خودکار طریقے سے بحال ہو جائیں گے۔',
                '/writer/commission',
                pg_catalog.jsonb_build_object('unpaid', v_actual_unpaid, 'limit', v_limit),
                false,
                pg_catalog.now()
            );
        END IF;
    END IF;

    RETURN v_actual_unpaid;
END;
$$;

REVOKE ALL ON FUNCTION public.reconcile_writer_unpaid_commission(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reconcile_writer_unpaid_commission(uuid) TO authenticated;

-- ------------------------------------------------------------------------------
-- 18. admin_commission_overview
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_commission_overview()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_writers jsonb;
    v_grace_days integer;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can inspect platform fee overview.';
    END IF;

    SELECT coalesce(overdue_grace_days, 3) INTO v_grace_days
    FROM public.platform_settings
    WHERE id = 1;

    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'writer_id', wp.id,
                'pen_name_english', wp.pen_name_english,
                'pen_name_urdu', wp.pen_name_urdu,
                'username', p.username,
                'custom_commission_rate', wp.custom_commission_rate,
                'unpaid_commission_balance_pkr', coalesce(wp.current_unpaid_commission, 0.00),
                'unpaid_commission_limit_pkr', coalesce(wp.unpaid_commission_limit, 5000.00),
                'percent_of_limit', round((coalesce(wp.current_unpaid_commission, 0.00) / coalesce(wp.unpaid_commission_limit, 5000.00)) * 100, 1),
                'is_orders_paused', coalesce(wp.is_orders_paused_for_commission, false),
                'total_accrued_pkr', (
                    SELECT coalesce(sum(l.platform_commission_pkr), 0.00)
                    FROM public.sales_ledger l
                    WHERE l.writer_id = wp.id
                ),
                'total_settled_pkr', (
                    SELECT coalesce(sum(cp.amount_pkr), 0.00)
                    FROM public.commission_payments cp
                    WHERE cp.writer_id = wp.id
                ),
                'pending_reports_count', (
                    SELECT count(*)
                    FROM public.commission_payment_reports cpr
                    WHERE cpr.writer_id = wp.id AND cpr.status = 'pending'
                ),
                'overdue_invoices_count', (
                    SELECT count(*)
                    FROM public.commission_invoices ci
                    WHERE ci.writer_id = wp.id
                      AND ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
                      AND ci.due_date IS NOT NULL
                      AND now() > (ci.due_date + (v_grace_days || ' days')::interval)
                )
            )
            ORDER BY wp.current_unpaid_commission DESC
        ),
        '[]'::jsonb
    )
    INTO v_writers
    FROM public.writer_profiles wp
    JOIN public.profiles p ON p.id = wp.id
    WHERE wp.status = 'approved';

    RETURN v_writers;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_commission_overview() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_commission_overview() TO authenticated;

-- ------------------------------------------------------------------------------
-- 19. admin_list_invoices
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_list_invoices(
    p_status text DEFAULT NULL,
    p_search text DEFAULT NULL,
    p_only_overdue boolean DEFAULT false,
    p_limit integer DEFAULT 50,
    p_offset integer DEFAULT 0
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_total integer := 0;
    v_invoices jsonb;
    v_grace_days integer;
    v_search text;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can list platform fee invoices.';
    END IF;

    SELECT coalesce(overdue_grace_days, 3) INTO v_grace_days
    FROM public.platform_settings
    WHERE id = 1;

    v_search := nullif(trim(p_search), '');

    SELECT count(*)
    INTO v_total
    FROM public.commission_invoices ci
    JOIN public.writer_profiles wp ON wp.id = ci.writer_id
    WHERE (p_status IS NULL OR ci.status::text = p_status)
      AND (v_search IS NULL OR (ci.invoice_number ILIKE '%' || v_search || '%' OR wp.pen_name_english ILIKE '%' || v_search || '%'))
      AND (NOT p_only_overdue OR (
          ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
          AND ci.due_date IS NOT NULL
          AND now() > (ci.due_date + (v_grace_days || ' days')::interval)
      ));

    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', ci.id,
                'invoice_number', ci.invoice_number,
                'writer_id', ci.writer_id,
                'writer_pen_name', wp.pen_name_english,
                'writer_pen_name_urdu', wp.pen_name_urdu,
                'period_start', ci.period_start,
                'period_end', ci.period_end,
                'total_sales_count', ci.total_sales_count,
                'total_gross_pkr', ci.total_gross_pkr,
                'total_commission_owed_pkr', ci.total_commission_owed_pkr,
                'amount_settled_pkr', ci.amount_settled_pkr,
                'remaining_owed_pkr', ci.total_commission_owed_pkr - ci.amount_settled_pkr,
                'status', ci.status,
                'due_date', ci.due_date,
                'is_overdue', (
                    ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
                    AND ci.due_date IS NOT NULL
                    AND now() > (ci.due_date + (v_grace_days || ' days')::interval)
                ),
                'created_at', ci.created_at
            )
            ORDER BY ci.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_invoices
    FROM (
        SELECT ci.*, wp.pen_name_english, wp.pen_name_urdu
        FROM public.commission_invoices ci
        JOIN public.writer_profiles wp ON wp.id = ci.writer_id
        WHERE (p_status IS NULL OR ci.status::text = p_status)
          AND (v_search IS NULL OR (ci.invoice_number ILIKE '%' || v_search || '%' OR wp.pen_name_english ILIKE '%' || v_search || '%'))
          AND (NOT p_only_overdue OR (
              ci.status IN ('invoiced', 'open', 'payment_reported', 'partially_paid')
              AND ci.due_date IS NOT NULL
              AND now() > (ci.due_date + (v_grace_days || ' days')::interval)
          ))
        ORDER BY ci.created_at DESC
        LIMIT p_limit OFFSET p_offset
    ) ci
    JOIN public.writer_profiles wp ON wp.id = ci.writer_id;

    RETURN jsonb_build_object(
        'total_count', v_total,
        'invoices', v_invoices
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_list_invoices(text, text, boolean, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_list_invoices(text, text, boolean, integer, integer) TO authenticated;

-- ------------------------------------------------------------------------------
-- 20. admin_list_commission_reports
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_list_commission_reports(
    p_status text DEFAULT 'pending',
    p_limit integer DEFAULT 50,
    p_offset integer DEFAULT 0
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_total integer := 0;
    v_reports jsonb;
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can inspect platform fee payment reports.';
    END IF;

    SELECT count(*)
    INTO v_total
    FROM public.commission_payment_reports cpr
    WHERE (p_status IS NULL OR p_status = 'all' OR cpr.status = p_status);

    SELECT coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', cpr.id,
                'invoice_id', cpr.invoice_id,
                'invoice_number', ci.invoice_number,
                'writer_id', cpr.writer_id,
                'writer_pen_name', wp.pen_name_english,
                'writer_username', p.username,
                'amount_pkr', cpr.amount_pkr,
                'transaction_reference', cpr.transaction_reference,
                'screenshot_path', cpr.screenshot_path,
                'writer_note', cpr.writer_note,
                'status', cpr.status,
                'is_duplicate_tid', cpr.is_duplicate_tid,
                'admin_note', cpr.admin_note,
                'created_at', cpr.created_at,
                'reviewed_at', cpr.reviewed_at
            )
            ORDER BY cpr.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_reports
    FROM (
        SELECT cpr.*
        FROM public.commission_payment_reports cpr
        WHERE (p_status IS NULL OR p_status = 'all' OR cpr.status = p_status)
        ORDER BY cpr.created_at DESC
        LIMIT p_limit OFFSET p_offset
    ) cpr
    JOIN public.commission_invoices ci ON ci.id = cpr.invoice_id
    JOIN public.writer_profiles wp ON wp.id = cpr.writer_id
    JOIN public.profiles p ON p.id = wp.id;

    RETURN jsonb_build_object(
        'total_count', v_total,
        'reports', v_reports
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_list_commission_reports(text, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_list_commission_reports(text, integer, integer) TO authenticated;

-- ------------------------------------------------------------------------------
-- 21. update_platform_settings
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_platform_settings(
    p_default_commission_rate numeric DEFAULT NULL,
    p_default_unpaid_commission_limit numeric DEFAULT NULL,
    p_min_novel_price_pkr integer DEFAULT NULL,
    p_max_novel_price_pkr numeric DEFAULT NULL,
    p_dispute_window_days integer DEFAULT NULL,
    p_max_orders_per_hour integer DEFAULT NULL,
    p_max_chapter_reads_per_window integer DEFAULT NULL,
    p_chapter_read_window_minutes integer DEFAULT NULL,
    p_invoice_due_days integer DEFAULT NULL,
    p_overdue_grace_days integer DEFAULT NULL,
    p_min_dispute_wait_hours integer DEFAULT NULL,
    p_verification_reminder_hours integer DEFAULT NULL,
    p_support_email text DEFAULT NULL,
    p_unpaid_commission_threshold_pkr numeric DEFAULT NULL,
    p_payment_verification_window_hours integer DEFAULT NULL,
    p_tips_enabled boolean DEFAULT NULL,
    p_tip_min_pkr integer DEFAULT NULL,
    p_tip_max_pkr integer DEFAULT NULL,
    p_max_tips_per_hour integer DEFAULT NULL,
    p_tip_daily_cap_pkr_per_reader integer DEFAULT NULL,
    p_tip_confirm_reminder_hours integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_caller_id uuid;
    v_old_settings jsonb;
    v_new_settings jsonb;
    v_effective_unpaid_limit numeric(12,2);
BEGIN
    v_caller_id := auth.uid();
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Restricted: Only platform administrators can update platform settings.';
    END IF;

    v_effective_unpaid_limit := coalesce(p_default_unpaid_commission_limit, p_unpaid_commission_threshold_pkr);

    SELECT pg_catalog.to_jsonb(s) INTO v_old_settings
    FROM public.platform_settings s
    WHERE id = 1;

    -- Validations
    IF p_default_commission_rate IS NOT NULL AND (p_default_commission_rate < 0 OR p_default_commission_rate > 100) THEN
        RAISE EXCEPTION 'Platform fee rate must be between 0 and 100.';
    END IF;
    IF v_effective_unpaid_limit IS NOT NULL AND v_effective_unpaid_limit < 0 THEN
        RAISE EXCEPTION 'Default unpaid platform fee limit must be non-negative.';
    END IF;
    IF p_min_novel_price_pkr IS NOT NULL AND (p_min_novel_price_pkr < 50 OR p_min_novel_price_pkr > 5000) THEN
        RAISE EXCEPTION 'Minimum novel price must be between 50 and 5000 PKR.';
    END IF;
    IF p_max_novel_price_pkr IS NOT NULL AND (p_max_novel_price_pkr < 50 OR p_max_novel_price_pkr > 5000) THEN
        RAISE EXCEPTION 'Maximum novel price must be between 50 and 5000 PKR.';
    END IF;
    IF p_dispute_window_days IS NOT NULL AND (p_dispute_window_days < 1 OR p_dispute_window_days > 90) THEN
        RAISE EXCEPTION 'Dispute window days must be between 1 and 90.';
    END IF;
    IF p_max_orders_per_hour IS NOT NULL AND (p_max_orders_per_hour < 1 OR p_max_orders_per_hour > 100) THEN
        RAISE EXCEPTION 'Max orders per hour must be between 1 and 100.';
    END IF;
    IF p_max_chapter_reads_per_window IS NOT NULL AND (p_max_chapter_reads_per_window < 1 OR p_max_chapter_reads_per_window > 1000) THEN
        RAISE EXCEPTION 'Max chapter reads per window must be between 1 and 1000.';
    END IF;
    IF p_chapter_read_window_minutes IS NOT NULL AND (p_chapter_read_window_minutes < 1 OR p_chapter_read_window_minutes > 1440) THEN
        RAISE EXCEPTION 'Chapter read window minutes must be between 1 and 1440.';
    END IF;
    IF p_invoice_due_days IS NOT NULL AND (p_invoice_due_days < 1 OR p_invoice_due_days > 90) THEN
        RAISE EXCEPTION 'Invoice due days must be between 1 and 90.';
    END IF;
    IF p_overdue_grace_days IS NOT NULL AND (p_overdue_grace_days < 0 OR p_overdue_grace_days > 60) THEN
        RAISE EXCEPTION 'Overdue grace days must be between 0 and 60.';
    END IF;
    IF p_min_dispute_wait_hours IS NOT NULL AND (p_min_dispute_wait_hours < 0 OR p_min_dispute_wait_hours > 168) THEN
        RAISE EXCEPTION 'Min dispute wait hours must be between 0 and 168.';
    END IF;
    IF p_verification_reminder_hours IS NOT NULL AND (p_verification_reminder_hours < 1 OR p_verification_reminder_hours > 168) THEN
        RAISE EXCEPTION 'Verification reminder hours must be between 1 and 168.';
    END IF;

    -- Tip controls validation
    IF p_tip_min_pkr IS NOT NULL AND (p_tip_min_pkr < 1 OR p_tip_min_pkr > 5000) THEN
        RAISE EXCEPTION 'Minimum tip amount must be between 1 and 5,000 PKR.';
    END IF;
    IF p_tip_max_pkr IS NOT NULL AND (p_tip_max_pkr < 1 OR p_tip_max_pkr > 50000) THEN
        RAISE EXCEPTION 'Maximum tip amount must be between 1 and 50,000 PKR.';
    END IF;
    IF p_max_tips_per_hour IS NOT NULL AND (p_max_tips_per_hour < 1 OR p_max_tips_per_hour > 100) THEN
        RAISE EXCEPTION 'Max tips per hour must be between 1 and 100.';
    END IF;
    IF p_tip_daily_cap_pkr_per_reader IS NOT NULL AND p_tip_daily_cap_pkr_per_reader < 100 THEN
        RAISE EXCEPTION 'Daily tip cap must be at least 100 PKR.';
    END IF;
    IF p_tip_confirm_reminder_hours IS NOT NULL AND (p_tip_confirm_reminder_hours < 1 OR p_tip_confirm_reminder_hours > 168) THEN
        RAISE EXCEPTION 'Tip confirmation reminder hours must be between 1 and 168.';
    END IF;

    UPDATE public.platform_settings
    SET default_commission_rate = coalesce(p_default_commission_rate, default_commission_rate),
        default_unpaid_commission_limit = coalesce(v_effective_unpaid_limit, default_unpaid_commission_limit),
        min_novel_price_pkr = coalesce(p_min_novel_price_pkr, min_novel_price_pkr),
        max_novel_price_pkr = coalesce(p_max_novel_price_pkr, max_novel_price_pkr),
        dispute_window_days = coalesce(p_dispute_window_days, dispute_window_days),
        max_orders_per_hour = coalesce(p_max_orders_per_hour, max_orders_per_hour),
        max_chapter_reads_per_window = coalesce(p_max_chapter_reads_per_window, max_chapter_reads_per_window),
        chapter_read_window_minutes = coalesce(p_chapter_read_window_minutes, chapter_read_window_minutes),
        invoice_due_days = coalesce(p_invoice_due_days, invoice_due_days),
        overdue_grace_days = coalesce(p_overdue_grace_days, overdue_grace_days),
        min_dispute_wait_hours = coalesce(p_min_dispute_wait_hours, min_dispute_wait_hours),
        verification_reminder_hours = coalesce(p_verification_reminder_hours, verification_reminder_hours),
        support_email = coalesce(nullif(pg_catalog.btrim(p_support_email), ''), support_email),
        tips_enabled = coalesce(p_tips_enabled, tips_enabled),
        tip_min_pkr = coalesce(p_tip_min_pkr, tip_min_pkr),
        tip_max_pkr = coalesce(p_tip_max_pkr, tip_max_pkr),
        max_tips_per_hour = coalesce(p_max_tips_per_hour, max_tips_per_hour),
        tip_daily_cap_pkr_per_reader = coalesce(p_tip_daily_cap_pkr_per_reader, tip_daily_cap_pkr_per_reader),
        tip_confirm_reminder_hours = coalesce(p_tip_confirm_reminder_hours, tip_confirm_reminder_hours),
        updated_at = pg_catalog.now()
    WHERE id = 1;

    SELECT pg_catalog.to_jsonb(s) INTO v_new_settings
    FROM public.platform_settings s
    WHERE id = 1;

    INSERT INTO public.audit_logs (
        actor_id, actor_role, action_type, entity_type, entity_id, previous_state, new_state, created_at
    ) VALUES (
        v_caller_id, 'admin', 'update_platform_settings', 'platform_settings', '1',
        v_old_settings, v_new_settings, pg_catalog.now()
    );

    RETURN v_new_settings;
END;
$$;

REVOKE ALL ON FUNCTION public.update_platform_settings(numeric, numeric, integer, numeric, integer, integer, integer, integer, integer, integer, integer, integer, text, numeric, integer, boolean, integer, integer, integer, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_platform_settings(numeric, numeric, integer, numeric, integer, integer, integer, integer, integer, integer, integer, integer, text, numeric, integer, boolean, integer, integer, integer, integer, integer) TO authenticated;

-- ------------------------------------------------------------------------------
-- 22. ONE-OFF SAFE UPDATE OF HISTORICAL PENDING NOTIFICATIONS & EMAIL OUTBOX
--     (Never touches append-only sales_ledger or audit_logs)
-- ------------------------------------------------------------------------------
DO $$
BEGIN
    -- Update unread notifications
    UPDATE public.notifications
    SET title = pg_catalog.replace(pg_catalog.replace(title, 'Commission', 'Platform Fee'), 'کمیشن', 'پلیٹ فارم فیس'),
        message = pg_catalog.replace(pg_catalog.replace(message, 'Commission', 'Platform Fee'), 'کمیشن', 'پلیٹ فارم فیس'),
        body = pg_catalog.replace(pg_catalog.replace(body, 'Commission', 'Platform Fee'), 'کمیشن', 'پلیٹ فارم فیس')
    WHERE (title ILIKE '%commission%' OR title LIKE '%کمیشن%'
       OR message ILIKE '%commission%' OR message LIKE '%کمیشن%'
       OR body ILIKE '%commission%' OR body LIKE '%کمیشن%');

    -- Update pending email outbox
    UPDATE public.email_outbox
    SET subject = pg_catalog.replace(pg_catalog.replace(subject, 'Commission', 'Platform Fee'), 'کمیشن', 'پلیٹ فارم فیس'),
        body_text = pg_catalog.replace(pg_catalog.replace(body_text, 'Commission', 'Platform Fee'), 'کمیشن', 'پلیٹ فارم فیس')
    WHERE status = 'pending'
      AND (subject ILIKE '%commission%' OR subject LIKE '%کمیشن%'
       OR body_text ILIKE '%commission%' OR body_text LIKE '%کمیشن%');
END;
$$;
